use vstd::prelude::*;

verus! {

    // Extracts the imaginary parts from a vector of complex numbers
    // represented as (real, imag) pairs.
    fn imag(val: Vec<(f64, f64)>) -> (res: Vec<f64>)
        ensures
            // The result has the same length as the input
            res.len() == val.len(),
            // For every valid index i, result[i] == imaginary part of val[i]
            forall |i: nat| i < val.len() ==>
                res.index(i) == val.index(i).1,
            // If the imaginary part is zero, the result is zero
            forall |i: nat| i < val.len() && val.index(i).1 == 0.0 ==>
                res.index(i) == 0.0,
            // If the input is non-zero as a complex number,
            // the result still equals the imaginary part
            forall |i: nat| i < val.len() && (val.index(i).0 != 0.0 || val.index(i).1 != 0.0) ==>
                res.index(i) == val.index(i).1
    {
        let mut res: Vec<f64> = Vec::new();
        let mut i: usize = 0;
        // Build up `res` by pushing val[i].1 for each i in range
        while i < val.len()
            invariant
                // 0 ≤ i ≤ val.len()
                0 <= i && i <= val.len(),
                // We have pushed exactly i elements so far
                res.len() == i,
                // And they match the imaginary parts of the first i inputs
                forall |j: nat| j < i ==>
                    res.index(j) == val.index(j).1,
            decreases
                val.len() - i,
        {
            let pair = val.index(i);
            let im   = pair.1;
            res.push(im);
            i = i + 1;
        }
        res
    }

}

